arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1954_12.json') as f:
    data = json.load(f)

# Print keys at top level
def print_structure(obj, indent=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(obj, list) and len(obj) > 0:
        print(' ' * indent + f'List of {len(obj)} items')
        if indent < 2:
            print_structure(obj[0], indent + 2)

print_structure(data)
"
